package main
import (
  "encoding/binary"
  "hash/crc32"
  "os"
  "fmt"
  "path/filepath"
)
func lfsr_keystream(seed uint32, n int) []byte {
  state := seed
  out := make([]byte, n)
  for i := 0; i < n; i++ {
    var b byte
    for bit := 0; bit < 8; bit++ {
      lsb := state & 1
      b |= byte(lsb) << bit
      state >>= 1
      if lsb != 0 { state ^= 0x80200003 }
    }
    out[i] = b
  }
  return out
}
func main() {
  data, _ := os.ReadFile(os.Args[1])
  key_id := binary.LittleEndian.Uint32(data[0:4])
  nonce := data[4:20]
  plen := binary.LittleEndian.Uint32(data[20:24])
  ct := data[24:24+plen]
  seed := key_id ^ crc32.ChecksumIEEE(nonce)
  ks := lfsr_keystream(seed, int(plen))
  pt := make([]byte, plen)
  for i := range pt { pt[i] = ct[i] ^ ks[i] }
  // write to verify/outputs if input is from verify/inputs
  if len(os.Args) > 1 {
    base := filepath.Base(os.Args[1])
    outpath := "/app/verify/outputs/" + base + ".txt"
    os.WriteFile(outpath, pt, 0644)
  }
  fmt.Printf("%s", pt)
}
